/**
 * Check if a given object implements the IncomeStatementItemUnusualItems interface.
 */
export function instanceOfIncomeStatementItemUnusualItems(value) {
    return true;
}
export function IncomeStatementItemUnusualItemsFromJSON(json) {
    return IncomeStatementItemUnusualItemsFromJSONTyped(json, false);
}
export function IncomeStatementItemUnusualItemsFromJSONTyped(json, ignoreDiscriminator) {
    if (json == null) {
        return json;
    }
    return {
        totalUnusualItems: json["total_unusual_items"] == null
            ? undefined
            : json["total_unusual_items"],
        totalUnusualItemsExcludingGoodwill: json["total_unusual_items_excluding_goodwill"] == null
            ? undefined
            : json["total_unusual_items_excluding_goodwill"],
    };
}
export function IncomeStatementItemUnusualItemsToJSON(json) {
    return IncomeStatementItemUnusualItemsToJSONTyped(json, false);
}
export function IncomeStatementItemUnusualItemsToJSONTyped(value, ignoreDiscriminator = false) {
    if (value == null) {
        return value;
    }
    return {
        total_unusual_items: value["totalUnusualItems"],
        total_unusual_items_excluding_goodwill: value["totalUnusualItemsExcludingGoodwill"],
    };
}
